const http = require('http');
const https = require('https');
const url = require('url');

class FeatureFlagStore {
  constructor() {
    this._flags = Object.create(null);
    this._metadata = {};
  }

  getFlag(name) {
    return this._flags[name];
  }

  setFlag(name, value) {
    this._flags[name] = value;
  }

  applyPatch(patch) {
    // Apply a configuration patch from the control plane
    // patch is a flat key-value map where keys use dot notation
    for (const key of Object.keys(patch)) {
      this._deepSet(this._metadata, key, patch[key]);
    }
  }

  _deepSet(target, path, value) {
    const segments = path.split('.');
    let current = target;
    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (typeof current[seg] !== 'object' || current[seg] === null) {
        current[seg] = {};
      }
      current = current[seg];
    }
    current[segments[segments.length - 1]] = value;
  }
}

class ProxyRouter {
  constructor(flagStore) {
    this.flagStore = flagStore;
    this.routes = Object.create(null);
    this.defaultBackend = 'http://localhost:8080';
  }

  resolveBackend(req) {
    const parsed = url.parse(req.url);
    const route = this.routes[parsed.pathname];
    if (route && route.backend) {
      return route.backend;
    }
    return this.defaultBackend;
  }

  isFeatureEnabled(featureName) {
    const flag = this.flagStore.getFlag(featureName);
    if (flag !== undefined) return !!flag;
    // Fall back to checking if there's a global override
    const globalOverride = {};
    return !!globalOverride[featureName];
  }
}

class NetworkProxy {
  constructor(config) {
    this.flagStore = new FeatureFlagStore();
    this.router = new ProxyRouter(this.flagStore);
    this.port = config.port || 3000;
    this.adminToken = config.adminToken;
    this.server = null;
  }

  start() {
    this.server = http.createServer((req, res) => {
      this._handleRequest(req, res);
    });
    this.server.listen(this.port);
    return this.server;
  }

  _handleRequest(req, res) {
    if (req.url.startsWith('/admin/')) {
      return this._handleAdmin(req, res);
    }
    return this._proxyRequest(req, res);
  }

  _handleAdmin(req, res) {
    const authHeader = req.headers['authorization'];
    if (!authHeader || authHeader !== `Bearer ${this.adminToken}`) {
      res.writeHead(401);
      return res.end('Unauthorized');
    }

    if (req.url === '/admin/flags' && req.method === 'POST') {
      return this._handleSetFlag(req, res);
    }
    if (req.url === '/admin/config' && req.method === 'PATCH') {
      return this._handleConfigPatch(req, res);
    }
    res.writeHead(404);
    res.end('Not found');
  }

  _handleSetFlag(req, res) {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
      try {
        const { name, value } = JSON.parse(body);
        if (typeof name !== 'string' || name.length === 0) {
          res.writeHead(400);
          return res.end('Invalid flag name');
        }
        this.flagStore.setFlag(name, value);
        res.writeHead(200);
        res.end('OK');
      } catch (e) {
        res.writeHead(400);
        res.end('Invalid JSON');
      }
    });
  }

  _handleConfigPatch(req, res) {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
      try {
        const patch = JSON.parse(body);
        if (typeof patch !== 'object' || patch === null || Array.isArray(patch)) {
          res.writeHead(400);
          return res.end('Invalid patch format');
        }
        // Validate all keys are strings and values are primitives
        for (const [key, val] of Object.entries(patch)) {
          if (typeof key !== 'string') {
            res.writeHead(400);
            return res.end('Keys must be strings');
          }
          if (typeof val === 'object' && val !== null) {
            res.writeHead(400);
            return res.end('Values must be primitives');
          }
        }
        this.flagStore.applyPatch(patch);
        res.writeHead(200);
        res.end('Config updated');
      } catch (e) {
        res.writeHead(400);
        res.end('Invalid JSON');
      }
    });
  }

  _proxyRequest(req, res) {
    if (!this.router.isFeatureEnabled('proxy_enabled')) {
      res.writeHead(503);
      return res.end('Service disabled');
    }

    const backend = this.router.resolveBackend(req);
    const parsed = url.parse(backend);
    const options = {
      hostname: parsed.hostname,
      port: parsed.port,
      path: req.url,
      method: req.method,
      headers: Object.assign({}, req.headers)
    };

    delete options.headers['host'];

    const proxyReq = http.request(options, (proxyRes) => {
      res.writeHead(proxyRes.statusCode, proxyRes.headers);
      proxyRes.pipe(res);
    });

    proxyReq.on('error', () => {
      res.writeHead(502);
      res.end('Bad Gateway');
    });

    req.pipe(proxyReq);
  }
}

const proxy = new NetworkProxy({
  port: parseInt(process.env.PORT) || 3000,
  adminToken: process.env.ADMIN_TOKEN || 'secret-token-12345'
});

proxy.start();
console.log(`Proxy listening on port ${proxy.port}`);

module.exports = { NetworkProxy, FeatureFlagStore, ProxyRouter };
